/* ZBZGames™ offline play and smart updates. Generated by tools/build_arcade.py.  Copyright © ZyeemZia
 * Network first, so a new release is never hidden behind old files; the saved
 * copy is used only with no connection. Every game is saved on first visit, so
 * the whole arcade plays offline. A new release waits and the page offers
 * "Update now"; the first visit takes over at once. Recovery: ?nosw=1 */
const CACHE = 'zbz-__VERSION__';
const PAGES = __PAGES__;
const ASSETS = __ASSETS__;

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE)
    .then(c => Promise.allSettled([...PAGES, ...ASSETS].map(u => c.add(new Request(u, { cache: 'reload' })))))
    .then(() => { if (!self.registration.active) return self.skipWaiting(); }));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k.startsWith('zbz-') && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});
self.addEventListener('message', e => { if (e.data && e.data.type === 'skip-waiting') self.skipWaiting(); });
self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  e.respondWith((async () => {
    try {
      const fresh = await fetch(req);
      if (fresh && fresh.ok && fresh.type === 'basic') { const copy = fresh.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
      return fresh;
    } catch {
      const hit = await caches.match(req, { ignoreSearch: true });
      if (hit) return hit;
      if (req.mode === 'navigate') return (await caches.match(url.pathname.startsWith('/play/') ? '/play/' : '/')) || Response.error();
      return Response.error();
    }
  })());
});
